      "sourceNotes": [],
      "text": "1. لا تقبل دعوى إلغاء القرارات الإدارية بعد مضي (60) ستين يومًا من تاريخ نشر القرار الإداري المطعون فيه أو إعلان صاحب الشأن به أو ثبوت علمه به علمًا يقينيًّا.\n2. ينقطع سريان هذا الميعاد بالتظلم والاعتراض إلى الجهة الإدارية المختصة حسب الإجراءات المقررة في التشريعات ذات العلاقة، ويجب على الجهة الإدارية أن تبت في التظلم خلال (60) ستين يومًا من تاريخ تقديمه، وإذا صدر القرار بالرفض وجب أن يكون مسببًا، ويعتبر فوات (60) ستين يومًا على تقديم التظلم دون صدور قرار من الجهات المختصة في التظلم بمثابة رفضه، ويحسب ميعاد رفع الدعوى من تاريخ الرفض الصريح أو الضمني حسب الأحوال.",
