      "text": "1.إذا نص هذا القانون على ميعاد حتمي لاتخاذ إجراء يحصل بالإعلان فلا يعتبر الميعاد مرعيًا إلا إذا تم تقديم الطلب أو مباشرة إجراءات الإعلان خلاله.\n2. إذا نص هذا القانون على أن يتم إجراء ما بالإيداع وجب أن تتم مباشرة إجراءات الإيداع خلال الميعاد المحدد في القانون.",
