      "sourceNotes": [],
      "text": "1. لغة المحاكم هي اللغة العربية، وعلى المحكمة أن تسمع أقوال الخصوم أو الشهود أو غيرهم الذين يجهلون اللغة العربية بواسطة مترجم بعد حلف اليمين، وفقًا للقانون.\n2. استثناء من أي نص ورد في أي قانون آخر، لرئيس مجلس القضاء الاتحادي أو رئيس الجهة القضائية المحلية حسب الأحوال، أن يُقرر في بعض الدوائر المخصصة لنظر المنازعات المتعلقة بالمواد التخصصية، أو في دعوى محددة، أو في بعض الدعاوى، أن تكون لغة المحاكمة والإجراءات والأحكام والقرارات فيها هي اللغة الإنجليزية، ويكون سماع الخصوم أو الشهود أو المحامين وتقديم اللوائح والمذكرات والطلبات والمستندات في هذه الدوائر باللغة الإنجليزية، وعلى المحكمة أن تسمع أقوال الخصوم أو الشهود أو غيرهم الذين يجهلون اللغة الإنجليزية بواسطة مترجم بعد حلف اليمين وفقًا للقانون، وذلك في الحالات ووفق الضوابط والشروط التي يصدر بها القرار.",
