      "sourceNotes": [],
      "text": "1. لا يجوز إجراء أي إعلان أو البدء في إجراء من إجراءات التنفيذ بواسطة القائم بالإعلان أو التنفيذ قبل الساعة السابعة صباحًا ولا بعد الساعة التاسعة مساءً، ولا في أيام العطلات الرسمية إلا في حالات الضرورة وبـإذن من القاضي المشرف أو رئيس الدائرة المختصة أو قاضي الأمور المستعجلة.\n2. إذا كان الإعلان بأحد وسائل التقنية سواء لأشخاص طبيعية أو اعتبارية خاصة فلا تسري المواعيد المنصوص عليها في البند (1) من هذه المادة فيما عدا المكالمات المسجلة.\n3. بالنسبة للحكومة والأشخاص الاعتبارية العامة يكون موعد الإعلان أو بدء التنفيذ فيما يتعلق بنشاطها في مواعيد عملها الرسمي فيما عدا الإعلان بإحدى وسائل التقنية.",
