      "text": "فيما عدا الدعاوى العينية المتعلقة بعقار في الخارج تختص المحاكم بنظر الدعاوى التي ترفع على المواطن والدعاوى التي ترفع على الأجنبي الذي له موطن أو محل إقامة في الدولة.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 19",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(1).md"
