      "label": "المادة 32",
      "title": "المادة (32)",
      "part": "الكتاب الأول: التداعي أمام المحاكم - الباب الأول: اختصاصات المحاكم",
      "chapter": "الفصل الثاني: الاختصاص النوعي للمحاكم",
