      "text": "إذا لم يكن للمدعى عليه موطن ولا محل إقامة في الدولة ولم يتيسر تعيين المحكمة المختصة وفق الأحكام المتقدمة يكون الاختصاص للمحكمة التي يقع في دائرتها موطن المدعي أو محل إقامته فإن لم يكن للمدعي موطن ولا محل إقامة في الدولة كان الاختصاص للمحكمة الاتحادية في العاصمة.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 42",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
