      "sourceNotes": [],
      "text": "1. في غير أحوال استخدام وسائل التقنية والاتصال عن بعد، يقوم مكتب إدارة الدعوى في اليوم التالي على الأكثر لقيد صحيفة الدعوى بتسليم صورة منها وما يرافقها من صور وأوراق ومستندات إلى الجهة المنوط بها أمر إعلانها، وذلك لإجراء الإعلان على النموذج المعد لهذا الغرض وحفظه، أما إذا كان الملف إلكترونيًّا فتمكن الجهة القضائية الخصوم من الاطلاع عليها في النظام أو إرسالها له إلكترونيًّا أو بإحدى الوسائل التقنية الأخرى.\n2. يجب إعلان صحيفة الدعوى إلكترونيًّا أو ورقيًّا خلال (10) عشرة أيام عمل من تاريخ تسليمها إلى القائم بالإعلان، وإذا حدد لنظر الدعوى جلسة تقع خلال هذا الميعاد فعندئذ يجب أن يتم الإعلان قبل الجلسة.\n3. لا يترتب البطلان على عدم مراعاة الميعاد المقرر في البندين (1) و(2) من هذه المادة.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 49",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(1).md"
