      "useCase": "اختبر أثر الحضور والغياب وحدود الوكالة والتفويض الخاص في جلسة افتراضية.",
      "sourceNotes": [],
      "text": "1. مع عدم الإخلال بقانون المحاماة، في اليوم المعين لنظر الدعوى أمام مكتب إدارة الدعوى أو المحكمة بحسب الأحوال يحضر الخصوم بأنفسهم أو بوكيل عنهم سواء محامٍ أو أحد الأقارب أو الأصهار إلى الدرجة الرابعة أو بوكيل من العاملين لديهم في حال كان الخصم شخصًا اعتباريًّا خاصًا، على أن يكون التوكيل -في الحالة الأخيرة- صادرًا من ممثله القانوني، مبينًا به صفته الوظيفية، ومصادقًا عليه من الكاتب العدل في كل خصومة.\n2. ويُشترط لصدور التوكيل الخاص في الدعوى المشار إليها في الحالة الأخيرة من البند (1) من هذه المادة، أن يتوافر في الوكيل الشروط الآتية:-\nأ‌. أن يكون مواطنًا متمتعًا بالأهلية القانونية الكاملة، وحاصلاً على مؤهل جامعي في القانون.\nب‌. أي شروط أخرى يُحددها قانون تنظيم مهنة المحاماة.\n3. يقبل حضور المندوب المرخص في مكتب المحامي بوكالة أمام مكتب إدارة الدعوى فقط وذلك في الدعاوى الموكل فيها المحامي.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 52",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
