      "sourceNotes": [],
      "text": "1. إذا لم يحضر المدعي ولا المدعى عليه حكمت المحكمة في الدعوى إذا كانت صالحة للحكم فيها وإلا قررت شطبها، فإذا انقضى (30) ثلاثون يومًا ولم يقدم أحد الخصوم طلبًا للسير فيها خلال تلك الفترة أو لم يحضر الطرفان بعد السير فيها اعتبرت كأن لم تكن وعلى مكتب إدارة الدعوى عرضها بعد مضي المدة المشار إليها في هذه الفقرة على القاضي المختص ليصدر قرارًا بذلك.\n2. للمحكمة أن تقرر شطب الدعوى إذا غاب المدعي في أي جلسة وحضر المدعى عليه ما لم يطلب الأخير الحكم في الدعوى.\n3. إذا كانت الدعوى أمام مكتب إدارة الدعوى يكون قرار الشطب واعتبار الدعوى كأن لم تكن بقرار يصدره القاضي المشرف مباشرة بعد مرور المدة المشار إليها في البند (1) من هذه المادة.",
