      "text": "1. صدور التوكيل من أحد الخصوم يجعل موطن وكيله معتبرًا في إعلان الأوراق اللازمة لسير الدعوى في درجة التقاضي الموكل فيها وعلى الخصم الذي لا يكون له وكيل بالبلد الذي به مقر المحكمة أن يتخذ له موطنًا فيها.\n2. لا يحول اعتزال الوكيل أو عزله دون سير الإجراءات في مواجهته إلا إذا أعلن الخصم بتعيين بدله أو بعزم الموكل على مباشرة الدعوى بنفسه.\n3. لا يجوز للوكيل أن يعتزل الوكالة في وقت غير لائق وبدون إذن من المحكمة.",
