      "sourceNotes": [],
      "text": "1. الدفع بعدم الاختصاص المحلي والدفع بإحالة الدعوى إلى محكمة أخرى لقيام ذات النزاع أمامها أو للارتباط، والدفع بالبطلان غير المتصل بالنظام العام، وسائر الدفوع المتعلقة بالإجراءات غير المتصلة بالنظام العام، يجب إبداؤها معًا قبل إبداء أي دفع إجرائي آخر أو طلب أو دفاع في الدعوى أو بعدم القبول وإلا سقط الحق فيما لم يبد منها كما يسقط حق الطاعن في هذه الدفوع إذا لم يبدها في صحيفة الطعن.\n2. يجب إبداء جميع الوجوه التي يبنى عليها الدفع المتعلق بالإجراءات غير المتصل بالنظام العام معًا وإلا سقط الحق فيما لم يبد منها.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 86",
