      "sourceNotes": [],
      "text": "1. للمحكمة من تلقاء نفسها أن تأمر بإدخال من ترى إدخاله لمصلحة العدالة أو لإظهار الحقيقة، وتُحدد المحكمة الجلسة التي يعلن إليها، كما تعين مركزه في الخصومة وتأمر بإعلانه لتلك الجلسة وذلك بالإجراءات المعتادة لرفع الدعوى.\n2. للمحكمة أن تكلف مكتب إدارة الدعوى بإعلان ملخص واف من طلبات الخصوم في الدعوى إلى أي شخص ترى لمصلحة العدالة أو لإظهار الحقيقة أن يكون على علم بها.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 98",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
