      "sourceNotes": [],
      "text": "1. يجوز وقف الدعوى إذا اتفق الخصوم على عدم السير فيها مدة لا تزيد على (6) ستة أشهر من تاريخ إقرار المحكمة لاتفاقهم، ولا يكون لهذا الوقف أثر في أي ميعاد حتمي يكون القانون قد حدده لإجراء ما. ولا يجوز لأي من الطرفين أن يعجل الدعوى خلال تلك المدة إلا بموافقة خصمه.\n2. إذا لم يعجل أحد الخصوم الدعوى خلال (8) الثمانية أيام التالية لنهاية الأجل اعتبر المدعي تاركًا دعواه والمستأنف تاركًا استئنافه وعلى مكتب إدارة الدعوى عرضها بعد مضي المدة المشار إليها في هذه الفقرة على القاضي المختص ليصدر قرارًا بذلك.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 103",
