      "sourceNotes": [],
      "text": "1. ينقطع سير الخصومة بحكم القانون بوفاة أحد الخصوم أو بفقده أهلية التقاضي أو بزوال صفة من كان يباشر الخصومة عنه من النائبين إلا إذا حدث شيء من ذلك بعد إقفال باب المرافعة في الدعوى، وإذا تعدد الخصوم قضت المحكمة باعتبار الخصومة منقطعة بالنسبة لمن قام به سبب الانقطاع وأجلت نظرها بالنسبة للباقين.\n2. لا تنقطع الخصومة بوفاة وكيل الدعوى ولا بانقضاء وكالته بالتنحي أو بالعزل، وللمحكمة أن تمنح أجلاً مناسبًا للخصم الذي توفي وكيله أو انقضت وكالته لتعيين وكيل آخر إذا رغب في ذلك.\n3. يترتب على انقطاع الخصومة وقف جميع مواعيد الإجراءات التي كانت جارية في حق الخصم الذي قام به سبب الانقطاع وبطلان جميع الإجراءات التي تحصل أثناء الانقطاع.",
