      "text": "1. تختم صورة الحكم التي يكون التنفيذ بموجبها بخاتم المحكمة ويوقعها الموظف المختص بعد أن يذيلها بالصيغة التنفيذية ولا تسلم إلا للخصم الذي له مصلحة في تنفيذ الحكم، ويُشترط أن يكون الحكم جائز التنفيذ أو يتم تذييل الحكم بالصيغة التنفيذية بالتوقيع الإلكتروني في حالة الحصول عليها عن بعد.\n2. لا يجوز تسليم صورة تنفيذية ثانية لذات الخصم إلا إذا فقدت الصورة الأولى أو تعذر استعمالها ويكون ذلك بأمر من القاضي أو رئيس الدائرة حسب الأحوال.\n3. يجوز إعطاء صورة مصدقة من نسخة الحكم إلكترونيًّا أو ورقيًّا لمن يطلبها من ذوي الشأن ولا تعطى لغيرهم إلا بإذن من القاضي أو رئيس الدائرة بحسب الأحوال.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 131",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(4).md"
