      "sourceNotes": [],
      "text": "1. استثناءً من أحكام المادتين (127) و(129) من هذا القانون، تفصل الدوائر المنصوص عليها في البند (2) من المادة (29) من هذا القانون، في الدعاوى المعروضة عليها، بقرار منها تودع أسبابه في ذات الجلسة.\n2. يجوز الطعن بالاستئناف على القرارات المشار إليها في البند (1) من هذه المادة، أمام محكمة الاستئناف المختصة المنعقدة في غرفة المشورة، وذلك وفقًا للقواعد والإجراءات والمواعيد المقررة للطعن على الأحكام.",
