      "sourceNotes": [],
      "text": "1. يجب على المحكمة عند إصدار الحكم أو القرار الذي تنتهي به الخصومة أمامها أن تحكم من تلقاء نفسها في مصروفات الدعوى.\n2. يحكم بمصروفات الدعوى على الخصم المحكوم عليه فيها، ويدخل في حساب المصروفات أتعاب المحاماة التي تقدرها المحكمة وفق الضوابط والمعايير المحددة في قانون تنظيم مهنة المحاماة وتكلفة ترجمة الإعلان، وإذا تعدد المحكوم عليهم جاز الحكم بتقسيم المصروفات بالتساوي أو بنسبة مصلحة كل منهم في الدعوى على حسب ما تقدره المحكمة، ولا يلزمون بالتضامن إلا إذا كانوا متضامنين في التزامهم المقضي به، ولا يتعدد مقابل أتعاب المحاماة بتعدد المحكوم لهم أو المحكوم عليهم أو بتعدد الوكلاء.\n3. يحكم بمصروفات التدخل على المتدخل إن كانت له طلبات مستقلة وحكم بعدم قبول تدخله أو برفض طلباته.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 133",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(4).md"
