      "sourceNotes": [],
      "text": "1. يجوز للمحكمة بقرار تصدره بناءً على طلب أحد الخصوم أو من تلقاء نفسها، بغير مرافعة، تصحيح ما يقع في قرارها أو حكمها من أخطاء مادية بحتة كتابية أو حسابية ويجري التصحيح على القرار أو الحكم محل التصحيح ويُوقع من رئيس الجلسة.\n2. يعد من قبيل الأخطاء المادية إدراج القرار أو الحكم وإصداره بصورة غير صحيحة في النظام الإلكتروني.\n3. إذا صدر القرار برفض التصحيح فلا يجوز الطعن فيه إلا مع الطعن في القرار أو الحكم نفسه، أما القرار الذي يصدر بالتصحيح فيجوز الطعن فيه على استقلال بطرق الطعن الجائزة في القرار أو الحكم موضوع التصحيح.",
