      "sourceNotes": [],
      "text": "1. للخصوم أن يطلبوا إلى المحكمة التي أصدرت الحكم تفسير ما وقع في منطوقه من غموض أو إبهام، ويقدم الطلب بالأوضاع المعتادة لرفع الدعوى ويعتبر الحكم الصادر بالتفسير متممًا من كل الوجوه للحكم الذي يفسره ويسري عليه ما يسري على هذا الحكم من القواعد الخاصة بطرق الطعن.\n2. للخصوم طلب تفسير القرارات والأوامر القضائية، ويقدم الطلب في هذه الحالة بذات طريقة تقديم القرار أو الأمر، ويسري عليها ذات الآثار المنصوص عليها في البند (1) من هذه المادة.",
