      "id": "civil-law-140",
      "number": 140,
      "label": "المادة 140",
      "title": "المادة (140)",
      "part": "الباب العاشر: الأوامر على العرائض",
      "chapter": "نص المادة",
      "topic": "الأوامر على العرائض والتظلم منها",
      "tags": [
        "الدعوى",
        "التنفيذ",
        "الجلسات",
        "الأوامر على العرائض",
        "الطعن"
      ],
      "modules": [
        "simulator",
        "ai",
        "quiz",
        "court",
        "map",
        "judgment",
        "execution"
      ],
      "useCase": "أنشئ أمراً على عريضة ودرّب على التظلم منه وأثره على التنفيذ.",
      "sourceNotes": [],
      "text": "1. في الأحوال التي يكون فيها للخصم وجه في استصدار أمر، يقدم عريضة بطلب إلى القاضي المختص أو إلى رئيس الدائرة التي تنظر الدعوى بعد قيدها وتكون هذه العريضة من نسختين ما لم تكن مقيدة إلكترونيًّا، بحيث تكون مشتملة على وقائع الطلب وأسانيده وموطن الطالب ومحل عمله وتعيين موطن مختار له في الدولة إذا لم يكن له موطن أو محل عمل فيها ويرفق بالعريضة المستندات المؤيدة لها.\n2. يصدر القاضي أو رئيس الدائرة -حسب الأحوال- أمره كتابةً على إحدى نسختي العريضة أو إلكترونيًّا في اليوم التالي لتقديمها على الأكثر، ولا يلزم ذكر الأسباب التي بني عليها الأمر إلا إذا كان مخالفًا لأمر سبق صدوره فعندئذ يجب ذكر الأسباب التي اقتضت إصدار الأمر الجديد وإلا كان باطلاً ويسجل هذا الأمر في محضر خاص أو في محضر الجلسة.\n3. ينفذ الأمر بكتاب يصدره القاضي أو رئيس الدائرة -حسب الأحوال- إلى الجهة المعنية وتُحفظ العريضة في الملف دون الحاجة إلى إعلان أو صيغة تنفيذية، وإذا تعذر التنفيذ لسبب راجع إلى شخص طبيعي أو اعتباري خاص، يجوز للقاضي أو رئيس الدائرة -حسب الأحوال- أن يحكم عليه بغرامة لا تقل عن (1.000) ألف درهم ولا تزيد على (10.000) عشرة آلاف درهم عن كل يوم تأخير في التنفيذ، ويكون ذلك بقرار مسبب لا يقبل الطعن فيه بأي طريق من طرق الطعن، وللقاضي أو رئيس الدائرة -بحسب الأحوال- أن يقيل المحكوم عليه من الغرامة كلها أو بعضها إذا أبدى عذرًا مقبولاً بعد تمام التنفيذ.\n4. يجوز تنفيذ حكم الغرامة المشار إليه في البند (3) من هذه المادة بواسطة مصدرها بعد إخطار المحكوم عليه.\n5. يسقط الأمر الصادر على عريضة إذا لم يقدم للتنفيذ خلال (15) خمسة عشر يومًا من تاريخ صدوره ولا يمنع هذا السقوط من استصدار أمر جديد.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 140",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(4).md"
