      "text": "1. يكون إعلان الطعن وفق الأوضاع المقررة في المادتين (9) و(10) من هذا القانون.\n2. إذا كان المطعون ضده هو المدعي أو المستأنف ولم يكن قد بين في صحيفة افتتاح الدعوى أو صحيفة الاستئناف العنوان الذي يعلن عليه، ولم يتضح هذا البيان من أوراق أخرى في الدعوى، أعلن بالطعن طبقًا للأوضاع المقررة في المادتين (9) و(10) من هذا القانون.",
