      "sourceNotes": [],
      "text": "1. لا يفيد من الطعن إلا من رفعه ولا يحتج به إلا على من رفع عليه، على أنه إذا كان الحكم صادرًا في موضوع غير قابل للتجزئة أو في التزام بالتضامن أو في دعوى يوجب القانون فيها اختصام أشخاص معينين جاز لمن فوت ميعاد الطعن من المحكوم عليهم أو قبل الحكم أن يطعن فيه أثناء نظر الطعن المرفوع في الميعاد من أحد زملائه منضمًا إليه في طلباته، فإن لم يفعل أمرت المحكمة الطاعن باختصامه في الطعن، وإذا رفع الطعن على أحد المحكوم لهم في الميعاد وجب اختصام الباقين ولو بعد فواته بالنسبة إليهم.\n2. إذا رفع الطعن في الميعاد من الضامن أو طالب الضمان في الحكم الصادر في الدعوى الأصلية، وكان دفاعهما فيها واحد جاز لمن فوت الميعاد أو قبل الحكم أن يطعن فيه منضمًا إلى زميله، وإذا رفع الطعن على أيهما في الميعاد جاز اختصام الآخر ولو بعد فواته بالنسبة إليه.\n3. يفيد الضامن وطالب الضمان من الطعن المرفوع من أيهما في الحكم الصادر في الدعوى الأصلية إذا اتحد دفاعهما فيها.",
