      "text": "1. لا يجوز إعادة المستندات إلى الخصوم الذين قدموها إلا بعد انتهاء مواعيد الطعن أو الفصل في الطعن المرفوع.\n2. يجوز أن تعطى صور من المستندات المشار إليها في البند (1) من هذه المادة لمن يطلبها من ذوي الشأن.\n3. إذا اقتضى الأمر تسليم أصل المستندات فيكون ذلك بأمر من القاضي أو رئيس الدائرة حسب الأحوال، ويحتفظ بصورة منها يصدق عليها أيهما وتختم بخاتم المحكمة.",
