      "sourceNotes": [],
      "text": "ميعاد الالتماس (30) ثلاثون يومًا ولا يبدأ في الحالات المنصوص عليها في البنود (1، 2، 3) من المادة (171) من هذا القانون إلا من اليوم الذي ظهر فيه الغش أو الذي أقر فيه فاعله بالتزوير أو حكم بثبوته أو الذي حكم فيه على شاهد الزور أو الذي ظهرت فيه الورقة المحتجزة، ويبدأ الميعاد في الحالة المنصوص عليها في البند (6) من المادة (171) من هذا القانون من اليوم الذي ظهر فيه الغش أو التواطؤ أو الإهمال الجسيم، ويبدأ الميعاد في الحالة المنصوص عليها في البند (7) من المادة (171) من هذا القانون من اليوم الذي يعلن فيه الحكم إلى المحكوم عليه أو من يمثله تمثيلاً صحيحًا.",
