      "sourceNotes": [],
      "text": "1. يفرض رسم ثابت قدره (2.000) ألفي درهم عن كل طعن بطريق النقض، وتُعفى الوزارات والهيئات والدوائر الحكومية وما في حكمها في الدولة من أداء هذا الرسم، ويتولى رئيس المحكمة أو من يندبه الفصل في طلبات تأجيل الرسوم أو الإعفاء منها، ويترتب على تقديم الطلب وقف سريان الميعاد المقرر للطعن.\n2. يجب على الطاعن بالنقض أن يودع خزانة المحكمة عند أداء الرسم المقرر للطعن مبلغ (3.000) ثلاثة آلاف درهم على سبيل التأمين يرد إليه إذا حكم بقبول طعنه، فإذا أقام الطاعنون طعنهم بصحيفة واحدة أُكتُفي بإيداع تأمين واحد، ويعفى من التأمين من يعفى من الرسوم القضائية.\n3. يفرض رسم ثابت قدره (1.000) ألف درهم عن كل طلب يتقدم به الطاعن لوقف تنفيذ الحكم المطعون فيه، وتعفى الجهات الوارد ذكرها في البند (1) من هذه المادة من أداء هذا الرسم.",
