      "sourceNotes": [],
      "text": "1. تسري على الطعن بالنقض القواعد والإجراءات التي تسري على الطعن بالاستئناف أمام محكمة الاستئناف فيما لا يتعارض مع نصوص هذا الفصل.\n2. يكون الطعن بالنقض في الأحكام الصادرة من المحاكم الاتحادية أمام المحكمة الاتحادية العليا في الحالات ووفقًا للإجراءات والقواعد المقررة في هذا الفصل ما لم يرد بشأنه نص خاص في قانون المحكمة الاتحادية العليا.",
