      "sourceNotes": [],
      "text": "للمدين إذا أراد الوفاء أن يعرض على الدائن عرضًا حقيقيًّا ما التزم بأدائه من نقود أو مستندات أو منقولات في موطن الدائن.\nويتم العرض بطلب يقدم إلى مكتب إدارة الدعوى أو إلى رئيس المحكمة الابتدائية -بحسب الأحوال- ويعلن إلى الدائن بوساطة القائم بالإعلان ويحرر به محضر يشتمل على بيان الشيء المعروض وشروط العرض وقبول المعروض أو رفضه، ويجوز إبداء العرض في الجلسة أمام المحكمة بدون إجراءات إذا كان من وجه إليه العرض حاضرًا.",
