      "useCase": "أنشئ عرضاً وإيداعاً صحيحاً وحدد أثر القبول أو الرفض والرجوع عن العرض.",
      "sourceNotes": [],
      "text": "1. إذا كان المعروض نقودًا أو أشياء أخرى مما يمكن نقلها وإيداعها خزانة المحكمة ورفضها من وجه إليه العرض أمر رئيس المحكمة الابتدائية أو رئيس الجلسة حسب الأحوال بإيداعها تلك الخزانة فورًا.\n2. إذا رفض العرض وكان المعروض مما لا يمكن إيداعه خزانة المحكمة أمر رئيس الجلسة أو رئيس المحكمة الابتدائية بناءً على طلب القائم بالإعلان -حسب الأحوال- بإيداعه المكان الذي يعينه وذلك إذا كان الشيء مما يتيسر نقله بغير مشقة أما إذا كان معدًّا للبقاء حيث وجد أو مما لا يتيسر نقله إلا بمشقة أمر بوضعه تحت الحراسة.\n3. إذا كان المعروض مما يسرع إليه التلف أو مما يتكلف نفقات باهظة في إيداعه أو حراسته جاز للمدين أو للقائم بالإعلان أن يطلب من رئيس المحكمة الابتدائية الأمر ببيعه بالمزاد العلني وإيداع الثمن خزانة المحكمة وإذا كان له سعر معروف في الأسواق أو كان التعامل فيه متداولاً فلا يجوز بيعه بالمزاد العلني إلا إذا تعذر البيع ممارسة بالسعر المعروف.\n4. للعارض أن يطلب إصدار قرار بصحة العرض.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 195",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(4).md"
