      "useCase": "حلّل دعوى مخاصمة القاضي أو عضو النيابة من شروطها إلى القبول والموضوع وآثار الحكم.",
      "sourceNotes": [],
      "text": "تجوز مخاصمة قضاة المحاكم الابتدائية ومحاكم الاستئناف وأعضاء النيابة العامة في الأحوال الآتية:-\n1. إذا وقع من القاضي أو عضو النيابة في عملهما غش أو تدليس أو خطأ مهني جسيم.\n2. في الأحوال الأخرى التي يقضي فيها القانون بمسئولية القاضي والحكم عليه بالتعويضات.",
