      "useCase": "حلّل دعوى مخاصمة القاضي أو عضو النيابة من شروطها إلى القبول والموضوع وآثار الحكم.",
      "sourceNotes": [],
      "text": "1. ترفع دعوى المخاصمة بتقرير في مكتب إدارة الدعوى بالمحكمة الاستئنافية التابع لها القاضي أو عضو النيابة يوقعه الطالب أو من يفوضه في ذلك، ويجب أن يشتمل التقرير على بيان أوجه المخاصمة وأدلتها وأن تودع معه الأوراق المؤيدة لها مع تأمين مقداره (1.000) ألف درهم.\n2. وتعرض المخاصمة للنظر في قبولها على إحدى دوائر محكمة الاستئناف بأمر من رئيسها بعد تبليغ صورة من التقرير إلى القاضي أو عضو النيابة.\n3. وتنظر في غرفة المداولة في أول جلسة تعقد بعد الأيام الثمانية التالية للتبليغ، ويقوم مكتب إدارة الدعوى بإخطار الطالب والمخاصم بالجلسة، وإذا كان القاضي المخاصم قاضيًا بمحكمة الاستئناف أو كان عضو النيابة المخاصم النائب العام أو محاميًا عامًّا على الأقل تولت الفصل في قبول المخاصمة إحدى دوائر النقض في غرفة المداولة فإذا حكمت بقبولها أحالت نظر موضوع المخاصمة إلى دائرة خاصة مؤلفة من (5) خمسة من قضاتها بحسب ترتيب أقدمياتهم.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 201",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(4).md"
