      "useCase": "أنشئ ملف تنفيذ وحدد قاضي التنفيذ المختص، ثم اختبر الإنابة والتظلم والاستئناف في واقعة افتراضية.",
      "sourceNotes": [],
      "text": "1. تتم الإنابة من قاضي التنفيذ المختص إلى قاضي التنفيذ المطلوب اتخاذ الإجراء في دائرته، ويرفق بها جميع المستندات القانونية المطلوبة لتنفيذها.\n2. يتخذ قاضي التنفيذ المناب القرارات اللازمة لتنفيذ الإنابة، ويفصل في إشكالات التنفيذ المعروضة عليه، ويتم التظلم من قراراته أو استئنافها أمام المحكمة المختصة -بحسب الأحوال- وفقًا للإجراءات والمدد المنصوص عليها في المادة (209) من هذا القانون.\n3. يعلم قاضي التنفيذ الذي أجرى تنفيذ الإنابة قاضي التنفيذ بما تم ويحول إليه أية أشياء تسلمها أو أموال أخرى نتيجة بيع المحجوزات.\n4. إذا وجد قاضي التنفيذ المناب أن هناك أسبابًا قانونية تمنع التنفيذ أو إذا تعذر عليه التنفيذ لأي سبب آخر، فعليه إعلام قاضي التنفيذ المختص بذلك.",
