      "useCase": "حلّل قابلية الحكم للنفاذ المعجل، واختر نوع الكفالة أو طلب وقف النفاذ عند قيام ضرر جسيم.",
      "sourceNotes": [],
      "text": "يجوز للمحكمة -بناءً على طلب ذوي الشأن- شمول حكمها بالنفاذ المعجل بكفالة أو بدونها في أيٍّ من الأحوال الآتية:-\n1. الأحكام الصادرة في المواد التجارية.\n2. إذا كان المحكوم عليه قد أقر بنشأة الالتزام ولو نازع في نطاقه أو ادعى انقضاءه.\n3. إذا كان الحكم قد صدر تنفيذًا لحكم سابق حائز لقوة الأمر المقضي أو مشمولاً بالنفاذ المعجل بغير كفالة أو كان مبنيًّا على سند رسمي لم يطعن بتزويره أو سند عرفي لم يجحد متى كان المحكوم عليه خصمًا في الحكم السابق أو طرفًا في السند.\n4. إذا كان الحكم صادرًا لمصلحة طالب التنفيذ في منازعة تنفيذ متعلقة به.\n5. إذا كان الحكم صادرًا بأداء أجور أو مرتبات أو تعويض ناشئ عن علاقة عمل.\n6. إذا كان الحكم صادرًا في إحدى دعاوى الحيازة أو بإخراج مستأجر العقار الذي انتهى عقده أو فسخ، أو بإخراج شاغل العقار الذي لا سند له متى كان حق المدعي غير مجحود أو كان ثابتًا بسند رسمي.\n7. في أية حالة أخرى إذا كان يترتب على تأخير التنفيذ ضرر جسيم بمصلحة المحكوم له على أن يبين ذلك في الحكم بيانًا وافيًا.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 216",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(5).md"
