      "sourceNotes": [],
      "text": "في الأحوال التي لا يجوز فيها تنفيذ الحكم أو الأمر إلا بكفالة، يكون للملزم بها الخيار بين أن يقدم كفيلاً مقتدرًا أو أن يودع خزانة المحكمة من النقود أو الأوراق المالية ما فيه الكفاية، أو أن يقبل إيداع ما يُحصل من التنفيذ خزانة المحكمة أو تسليم الشيء المأمور بتسليمه في الحكم أو الأمر إلى حارس أمين.",
