      "text": "استثناءً من أحكام المادة (207) من هذا القانون، يجري تنفيذ أحكام وقرارات الأحوال الشخصية تحت إشراف قاضٍ مختص يندب في مقر كل محكمة، ويعاونه في ذلك عددٍ كافٍ من القائمين على التنفيذ والأخصائيين الاجتماعيين.\nوتسري أحكام وإجراءات التنفيذ الواردة في هذا القانون فيما خلت منه المواد الواردة في هذا الفصل.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 226",
