      "sourceNotes": [],
      "text": "1. تكون الأحكام الصادرة من قاضي تنفيذ الأحوال الشخصية في منازعات التنفيذ الموضوعية قابلة للاستئناف خلال (15) خمسة عشر يومًا من تاريخ صدورها.\n2. إذا كان لطالب التنفيذ أو المنفذ ضده ملفات تنفيذ أخرى متعلقة بمسائل أحوال شخصية بينهما تنفيذ في دوائر محاكم أخرى، فيجوز ضمها لنظرها أمام قاضي التنفيذ الذي قيد أمامه أول ملف تنفيذ، ما لم يتفق الطرفان على خلاف ذلك.",
