      "useCase": "ابنِ الخطوة التنفيذية من لائحة الطلب وإعلان السند ومهلة الوفاء إلى الإيداع أو التسليم وإثبات الواقعة.",
      "sourceNotes": [],
      "text": "1. يتعين على طالب التنفيذ أن يبين الإجراءات المطلوب اتخاذها في لائحة الطلبات التنفيذية عند القيد إلكترونيًّا أو ورقيًّا.\n2. يجب أن يسبق التنفيذ إعلان السند التنفيذي طبقًا لإجراءات الإعلان المقررة في هذا القانون.\n3. يجب أن يشتمل الإعلان على بيان المطلوب، وتكليف المدين بالوفاء به خلال (7) سبعة أيام من تاريخ إعلانه وتعيين موطن مختار لطالب التنفيذ في دائرة المحكمة التي يجري فيها التنفيذ إذا لم يكن موطنه الأصلي أو محل عمله فيه أو موطنه المختار.\n4. إذا كان السند التنفيذي صادرًا استنادًا إلى عقد فتح اعتماد وجب أن يعلن معه مستخرج بحساب المدين من واقع دفاتر الدائن التجارية.\n5. في حال التنفيذ بإخلاء عقار أو بتسليم أموال منقولة أو عقارية يجب أن يشتمل إعلان السند التنفيذي على تحديد كافٍ لهذه الأموال.\n6. إذا اشتمل السند التنفيذي على تحديد ميعاد للإخلاء أو التسليم وجب أن يتضمن الإعلان هذا الميعاد.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 233",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(5).md"
