      "sourceNotes": [],
      "text": "1. استثناءً من أحكام المادة (233) من هذا القانون، ودون الإخلال بقواعد الحجز التحفظي على المنقول والعقار وحجز ما للمدين لدى الغير وما ينص عليه أي تشريع آخر، يجوز لقاضي التنفيذ أن يأمر بالحجز التحفظي على أموال المدين طبقًا للقواعد والإجراءات المقررة في هذا القانون قبل إعلانه بالسند التنفيذي إذا تبين له ما يشير إلى سعي المدين بتهريب أمواله من واقع تقرير المعلومات الائتماني أو من قرائن الحال أو فقدان الدائن للضمان العام.\n2. لقاضي التنفيذ أن يأمر بالاستعلام عن أموال المدين قبل إعلانه بالسند التنفيذي.\n3. لقاضي التنفيذ منع المنفذ ضده من السفر قبل الإعلان بالسند إذا تبين له ما يشير إلى سعي المدين لمغادرة الدولة.",
