      "text": "1. إذا تُوفي المدين أو فقد أهليته أو زالت صفة من يباشر الإجراءات بالنيابة عنه قبل البدء في التنفيذ أو قبل إتمامه فلا يجوز التنفيذ أو الاستمرار قبل ورثته المبينة أسماؤهم وصفاتهم في الإعلام الشرعي أو من يقوم مقامه إلا بعد مضي (7) سبعة أيام من تاريخ إعلانهم بالسند التنفيذي.\n2. إذا تُوفي الدائن أو فقد أهليته أو زالت صفة من يباشر الإجراءات بالنيابة عنه بعد البدء في التنفيذ أوقفت إجراءات التنفيذ وكل المواعيد السارية في حقه حتى يعجلها أحد طرفي التنفيذ.\n3. يجوز قبل انقضاء (3) ثلاثة أشهر من تاريخ الوفاة أن يتم الإعلان المشار إليه في البندين (1) و(2) من هذه المادة إلى الورثة كافة في آخر موطن كان يقيم فيه مورثهم بغير بيان أسمائهم وصفاتهم، وإذا كان الإعلان بعد انقضاء هذه المدة يجب إعلانهم بصفاتهم وأشخاصهم.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 237",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(5).md"
