      "useCase": "صنّف الإشكال إلى وقتي أو موضوعي، وحدد أثره على الاستمرار في التنفيذ والتأمين وطرق التظلم.",
      "sourceNotes": [],
      "text": "1. إذا عرض عند التنفيذ إشكال وكان المطلوب فيه إجراءً وقتيًّا فعلى القائم بالتنفيذ أو المنفذ ضده أو ذو الشأن أن يعرض هذا الإشكال على قاضي التنفيذ ليقرر وقف التنفيذ أو المضي فيه.\n2. في جميع الأحوال لا يجوز للقائم بالتنفيذ، أن يتم التنفيذ قبل أن يصدر القاضي قراره، ويتم التظلم من هذا القرار وفق البند (1) من المادة (209) من هذا القانون.\n3. إذا تبين لقاضي التنفيذ أن الإشكال المقدم يعتبر منازعة تنفيذ موضوعية، صرح لمقدمها بقيدها خلال أجل (7) سبعة أيام عمل من تاريخ التصريح، ويستمر التنفيذ ما لم يصدر في المنازعة قرار بوقف التنفيذ.\n4. إذا تبين لقاضي التنفيذ أن الإشكال المرفوع يتعلق بدعوى ملكية عقار قيدت بالإجراءات المعتادة لرفع الدعوى أمام المحكمة المختصة ترتب على رفعه وقف التنفيذ إلا إذا أمرت المحكمة بخلاف ذلك.\n5. لا يترتب على تقديم أي إشكال لاحق، أو بعد رفع أي منازعة تنفيذ موضوعية وقف التنفيذ، ما لم يقرر قاضي التنفيذ خلاف ذلك، أو يقرر القانون وجوب وقف التنفيذ.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 239",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
