      "sourceNotes": [],
      "text": "إذا لم يتم الحجز في يوم واحد جاز إتمامه في يوم أو أيام متتالية متتابعة، وعلى القائم بالتنفيذ أن يتخذ ما يلزم للمحافظة على الأشياء المحجوزة والمطلوب حجزها إلى أن يتم المحضر، ويجب التوقيع على المحضر كلما توقفت إجراءات الحجز.\nومع ذلك إذا اقتضى الحال استمر القائم بالتنفيذ بإجراءات الحجز بعد المواعيد المقررة في المادة (7) من هذا القانون، أو في أيام العطل الرسمية جاز له إتمامها دون حاجة لاستصدار إذن من قاضي التنفيذ.",
