      "useCase": "صغ طلب حجز تحفظي، واربط سبب الخطر بالإجراء اللاحق وميعاد دعوى ثبوت الحق وأثر التظلم.",
      "sourceNotes": [],
      "text": "يجوز لمالك المنقول ومن له حق عيني عليه أو حق في حبسه أن يطلب توقيع الحجز التحفظي عليه عند من يحوزه، وذلك بموجب عريضة مشتملة على بيان وافٍ عن المنقول المطلوب الحجز عليه.",
