      "useCase": "صغ طلب حجز تحفظي، واربط سبب الخطر بالإجراء اللاحق وميعاد دعوى ثبوت الحق وأثر التظلم.",
      "sourceNotes": [],
      "text": "1. إذا لم يكن بيد الدائن سند تنفيذي أو كان دينه معين المقدار، جاز لقاضي الأمور المستعجلة أن يأمر بالحجز ويقدر دين الحاجز تقديرًا مؤقتًا وذلك بناءً على عريضة مسببة يقدمها طالب الحجز، وللقاضي قبل إصدار الأمر أن يجري تحقيقًا مختصرًا إذا لم تكن المستندات المؤيدة للطلب كافية.\n2. يجب في حالة الحجز على عقار أن يقدم مع العريضة صورة رسمية من سند ملكية ذلك العقار المطلوب الحجز عليه.\n3. إذا كانت الدعوى مرفوعة بالحق من قبل أمام المحكمة المختصة جاز طلب الأمر بالحجز المشار إليه في البند (1) من هذه المادة من المحكمة التي تنظر الدعوى.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 249",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
