      "useCase": "صغ طلب حجز تحفظي، واربط سبب الخطر بالإجراء اللاحق وميعاد دعوى ثبوت الحق وأثر التظلم.",
      "sourceNotes": [],
      "text": "1. يتبع في الحجز التحفظي على المنقولات القواعد والإجراءات المنصوص عليها في المواد من (264) إلى (282) من هذا القانون عدا ما يتعلق منها بتحديد يوم البيع إلا إذا كانت هذه المنقولات عرضة للتلف فيراعى نص البند (2) من المادة (273) من هذا القانون، ويتبع في الحجز التحفظي على العقارات القواعد والإجراءات المنصوص عليها في المواد من (285) إلى (305) من هذا القانون عدا ما يتعلق منها بتقديم السند التنفيذي وإجراءات البيع بالمزاد.\n2. يجب على الحاجز خلال (8) ثمانية أيام من تاريخ صدور قرار الحجز أن يرفع أمام المحكمة المختصة الدعوى بثبوت الحق، وذلك في الأحوال التي يكون فيها الحجز بأمر من قاضي الأمور المستعجلة وإلا اعتبر الحجز كأن لم يكن. ويعتبر الحجز كذلك كأن لم يكن إذا لم يبدأ في تنفيذ الحكم النهائي الصادر لصالحه خلال (30) ثلاثين يومًا من تاريخ صيرورته نهائيًّا.\n3. لمن صدر الأمر برفض طلبه وللمحجوز عليه ولذوي الشأن أن يتظلم من أمر الحجز أمام قاضي الأمور المستعجلة أو أمام المحكمة المختصة -بحسب الأحوال- سواءً كان التظلم في موضوع الحجز أو مواعيده، وفي جميع الأحوال ينقضي الحجز إذا صدر حكم نهائي برفض دعوى ثبوت الحق.\n4. إذا صدر حكم برفض التظلم وكان واجب التنفيذ أو صار كذلك تتبع الإجراءات المقررة للبيع في المواد من (264) إلى (282) ومن (285) إلى (305) من هذا القانون، بحسب الأحوال أو يجري التنفيذ بتسليم المنقول في الحالة المشار إليها في المادة (248) من هذا القانون.\n5. تبقى إجراءات الحجز التي اتخذت بموجب حكم أو قرار واجب النفاذ سارية ما لم يكن الحكم أو القرار الصادر بإلغائها أصبح نهائيًّا.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 250",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(5).md"
