      "sourceNotes": [],
      "text": "1. إذا أوقع مؤجر العقار الحجز على منقولات المستأجرين من الباطن طبقًا للبند (2) من المادة (247) من هذا القانون وجب أن توجه الإجراءات إلى كل من المستأجر الأصلي والمستأجر من الباطن.\n2. يعتبر إعلان الحجز إلى المستأجر من الباطن بمثابة حجز أيضًا تحت يده على الأجرة.\n3. إذا كان المستأجر الأصلي غير ممنوع من التأجير من الباطن جاز للمستأجر من الباطن أن يطلب رفع الحجز على منقولاته مع بقاء الحجز تحت يده على الأجرة.",
