      "sourceNotes": [],
      "text": "1. يجوز لكل دائن أن يطلب من المحكمة المختصة أو قاضي الأمور المستعجلة الحجز على ما يكون لمدينه لدى الغير من المنقولات أو ديون ولو كانت مؤجلة أو معلقة على شرط أو كانت محلاً للنزاع.\n2. إذا لم يكن الحجز موقعًا على منقول أو دين بذاته فإنه يتناول كل ما يكون للمحجوز عليه من منقولات في يد المحجوز لديه وديون في ذمته إلى وقت التقرير بما في الذمة.\n3. يوقع حجز ما للمدين لدى الغير على منقولات المدين التي في حيازة ممثله القانوني.",
