      "text": "1. إذا لم يحصل الإيداع طبقًا للمادة (255) أو المادتين (244) و(245) من هذا القانون وجب على المحجوز لديه أن يقرر بما في ذمته إلى الجهة الآمرة بالحجز خلال (7) سبعة أيام من إعلانه بالحجز، ويذكر في التقرير مقدار الدين وسببه وأسباب انقضائه إن وجدت، وإذا كان تحت يد المحجوز لديه منقولات وجب عليه أن يرفق بالتقرير بيانًا مفصلاً عنها.\n2. إذا كان الحجز تحت يد الحكومة أو إحدى المؤسسات العامة أو الهيئات العامة أو أحد البنوك فيكون التقرير بما في الذمة بواسطة كتاب ترسله الجهة المحجوز لديها إلى الجهة الآمرة بالحجز في الميعاد سالف الذكر يتضمن بيانات التقرير.\n3. لا يعفى المحجوز لديه من واجب التقرير بما في الذمة أن يكون غير مدين للمحجوز عليه، وعندئذ يجوز أن يتم التقرير ببيان يقدمه إلى الجهة الآمرة بالحجز، كما أن سر المهنة لا يعفيه من واجب التقرير بما في الذمة.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 256",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(5).md"
