      "sourceNotes": [],
      "text": "1. إذا لم يقرر المحجوز لديه بما في ذمته على الوجه المقرر قانونًا أو قدم تقريرًا غير كافٍ أو قرر غير الحقيقة، أو أخفى الأوراق الواجب عليه إيداعها لتأييد التقرير جاز الحكم عليه للدائن الذي حصل على سند تنفيذي بدينه بالمبلغ المحجوز من أجله وذلك بدعوى ترفع بالإجراءات المعتادة ولا تقبل دعواه بعد مضي (3) ثلاث سنوات من تاريخ صدور قرار التقرير بما في الذمة.\n2. يعتبر تنفيذ الحكم الصادر ضد المحجوز لديه وفاء لحق الحاجز قبل المحجوز عليه، ولا يخل ذلك برجوع المحجوز لديه على المحجوز عليه بما أدَّاه للحاجز.\n3. لا يصدر الحكم إذا تلافى المحجوز لديه السبب الذي رفعت بسببه الدعوى حتى إقفال باب المرافعة فيها ولو أمام محكمة الاستئناف.\n4. يجب في جميع الأحوال إلزام المحجوز لديه بمصروفات الدعوى والتعويضات المترتبة على تقصيره أو تأخيره.",
