      "sourceNotes": [],
      "text": "يجوز للدائن أن يوقع الحجز تحت يد نفسه على ما يكون مدينًا به لمدينه، ويكون ذلك بأمر من القاضي المختص يعلن إلى المدين مشتملاً على البيانات الواجب ذكرها في ورقة إبلاغ الحجز.\nفإذا لم يكن بيد الحاجز سند تنفيذي أو حكم، تتبع الإجراءات والمدد المنصوص عليها في البنود (2، 3، 4، 5) من المادة (250) من هذا القانون.",
