      "useCase": "أدر حجز المنقول: حرّر المحضر، عيّن الحارس، وثّق الإعلان، ثم انتقل إلى البيع بالمزاد ودعوى الاسترداد.",
      "sourceNotes": [],
      "text": "1. إذا كان الحجز على مصوغات أو سبائك ذهبية أو فضية أو من معدن نفيس آخر أو على مجوهرات أو أحجار كريمة وجب وزنها وبيان أوصافها بدقة في محضر الحجز، وتقوم هذه الأشياء بمعرفة خبير يعينه قاضي التنفيذ من تلقاء نفسه أو بناءً على طلب طالب التنفيذ.\n2. يجوز بهذه الطريقة تقويم الأشياء الفنية والأشياء النفيسة الأخرى بناءً على طلب الحاجز أو المحجوز عليه، وفي جميع الأحوال يرفق تقرير الخبير بمحضر الحجز.\n3. يجب إذا اقتضى الحال نقلها لوزنها أو تقويمها أن توضع في حرز مختوم وأن يذكر ذلك في المحضر مع وصف الأختام وتودع في خزانة المحكمة.\n4. إذا وقع الحجز على نقود أو عملة ورقية وجب على مندوب التنفيذ أن يبين أوصافها ومقدارها في المحضر ويودعها خزانة المحكمة.",
