      "sourceNotes": [],
      "text": "1. يعين القائم بالتنفيذ حارسًا للأشياء المحجوزة، ويقوم باختيار الحارس إذا لم يأت الحاجز أو المحجوز عليه بشخص مقتدر، وجب تعيين المحجوز عليه إذا طلب هو ذلك، إلا إذا خيف التبديد وكان لذلك أسباب معقولة تبين في المحضر، وعندئذٍ يذكر رأي المحجوز عليه في تلك الأسباب ويعرض أمرها فورًا على قاضي التنفيذ لاتخاذ قراره في هذا الشأن.\n2. إذا لم يجد القائم بالتنفيذ في مكان الحجز من يقبل الحراسة وكان المدين حاضرًا كلفه بالحراسة ولا يعتد برفضه إياها، أما إذا لم يكن حاضرًا وجب عليه أن يتخذ جميع التدابير الممكنة للمحافظة على الأشياء المحجوزة وأن يرفع الأمر على الفور لقاضي التنفيذ ليأمر إما بنقلها وإيداعها عند أمين يقبل الحراسة يختاره الحاجز أو القائم بالتنفيذ وإما بتكليف الشرطة بالحراسة مؤقتًا.",
