      "sourceNotes": [],
      "text": "1. إذا كان الحارس موجودًا وقت الحجز سلمت إليه الأشياء المحجوزة في مكان حجزها بعد التوقيع منه على محضر الحجز وتسليمه صورة منه، فإذا كان غائبًا أو عين فيما بعد وجب جرد الأشياء المحجوزة وتسليمها إليه بعد التوقيع على محضر الجرد وتسليمه صورة منه.\n2. إذا امتنع الحارس عن التوقيع على محضر الحجز أو الجرد أو رفض تسلم صورته وجب على القائم بالتنفيذ أن يستبدل به حارسًا آخر، وإلا فعليه أن يعرض الأمر على قاضي التنفيذ فورًا ليقرر ما يراه مناسبًا.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 267",
