      "sourceNotes": [],
      "text": "1. إذا انتقل القائم بالتنفيذ لتوقيع الحجز على منقولات سبق حجزها لدى المدين وجب على الحارس عليها أن يبرز له صورة محضر الحجز ويقدم الأشياء المحجوزة، وعلى القائم بالتنفيذ أن يجردها في محضر ويحجز على ما لم يسبق حجزه ويجعل حارس الحجز الأول حارسًا عليها إن كانت في ذات المكان.\n2. يعلن هذا المحضر خلال (3) ثلاثة أيام عمل إلى الحاجز الأول والمدين والحارس إذا لم يكن حاضرًا، كما يعلن إلى الجهة التي أمرت بتوقيع الحجز الأول.\n3. يترتب على هذا الإعلان بقاء الحجز لمصلحة الحاجز الثاني ولو نزل عنه الحاجز الأول، كما يعتبر حجزًا تحت يد القائم بالتنفيذ على المبالغ المتحصلة من البيع.\n4. إذا كان الحجز الأول على المنقولات باطلاً فلا يؤثر ذلك على الحجوز اللاحقة عليه إذا وقعت صحيحة في ذاتها.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 271",
