      "sourceNotes": [],
      "text": "1. يجوز للمدين بعد إتمام الحجز أن يقدم لقاضي التنفيذ طلبًا ببيع الأموال المحجوزة لأحد المشترين ويرفق بطلبه ثمن البيع وموافقة المشتري عليه، ويعرض ذلك على الدائن الحاجز أو الدائنين الحاجزين إن تعددوا إذا كان ثمن المبيع أقل من الدين المحجوز من أجله وذلك خلال (7) سبعة أيام من تاريخ تقديم الطلب، فإذا لم يعترضوا خلال (7) سبعة أيام من تاريخ إخطارهم أو عند موافقتهم يتم إجراء البيع وإيداع الثمن خزينة المحكمة لصالح الدائنين.\n2. مع مراعاة أحكام المادة (276) من هذا القانون، فإنه في حالة تعذر الحصول على موافقة الدائن الحاجز أو رفضه يجري تحديد يوم البيع وساعته ومكانه بمعرفة قاضي التنفيذ. ويجب على القائم بالتنفيذ عقب ذلك مباشرة أن يدرج الإعلان على الموقع الإلكتروني للمحكمة، أو أن يلصق على باب المكان الذي به الأشياء المحجوزة وكذلك باللوحات المعدة لذلك بالمحكمة.\n3. يجوز لقاضي التنفيذ أن يأمر بإعلان ذلك في إحدى الصحف اليومية الصادرة في الدولة باللغة العربية أو الأجنبية عند الاقتضاء أو غيرها من الوسائل التقنية ووسائل الإعلام المختلفة، أو بأي وسيلة أخرى يراها مناسبة.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 272",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
