      "sourceNotes": [],
      "text": "1. يجري البيع في المكان الذي توجد فيه الأشياء المحجوزة أو في المكان الذي خُصص بمعرفة قاضي التنفيذ لبيع المحجوزات إلا إذا اقتضت المصلحة خلاف ذلك، ويكون إجراؤه بعد (3) ثلاثة أيام على الأقل من تاريخ إتمام إجراءات إدراج الإعلان على الموقع الإلكتروني للمحكمة أو اللصق أو النشر، ويسمح لمن يرغب بمعاينة المحجوزات خلال الفترة المذكورة.\n2. إذا كانت الأشياء المحجوزة عرضة للتلف أو بضائع عرضة لتقلب الأسعار فلقاضي التنفيذ أن يأمر بإجراء البيع في المكان الذي يراه ومن ساعة لساعة على حسب الأحوال وذلك بناءً على طلب يقدم إليه من الحارس أو أحد ذوي الشأن أو القائم بالتنفيذ.\n3. إذا لم يتقدم الدائن بمباشرة بيع المحجوزات خلال (30) ثلاثين يومًا من بعد الحجز -ما لم توجد موانع قانونية- لقاضي التنفيذ أن يباشر إجراءات البيع أو رفع الحجز عن المحجوزات بحسب الأحوال وتخصم المصروفات من حصيلة البيع.",
