      "text": "إذا لم يتقدم أحد لشراء المصوغات أو السبائك من الذهب أو الفضة أو الحلي والمجوهرات والأحجار الكريمة والأشياء المقومة بقيمتها حسب تقدير أهل الخبرة ولم يقبل الدائن استيفاء دينه عينًا بهذه القيمة امتد أجل بيعها إلى اليوم التالي إذا لم يكن عطلة أو إلى أول يوم عمل عقب العطلة، فإذا لم يتقدم مشتر بالقيمة المقدرة أجل البيع إلى يوم آخر وأعيد اللصق أو النشر على الوجه المبين في المواد السابقة وعندئذ يعرض مندوب التنفيذ الأمر على القاضي المختص ليأمر برسو المزاد بالثمن الذي يراه مناسبًا ولو في موعد آخر.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 276",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(5).md"
