      "useCase": "أدر حجز المنقول: حرّر المحضر، عيّن الحارس، وثّق الإعلان، ثم انتقل إلى البيع بالمزاد ودعوى الاسترداد.",
      "sourceNotes": [],
      "text": "إذا لم يدفع الراسي عليه المزاد الثمن فورًا، يجوز للقاضي إمهاله مدة (5) خمسة أيام للدفع، وبعد انقضاء المدة المشار إليها دون التزام الراسي عليه المزاد بالدفع، وجب إعادة البيع على ذمته بالطريقة المتقدمة بأي ثمن كان، ويُلزم بما ينقص من الثمن، كما يلتزم بمصاريف ورسوم إعادة البيع ويعتبر محضر البيع سندًا تنفيذيًّا بفرق الثمن بالنسبة إليه.\nولا يكون له حق في أي زيادة في الثمن بل يستحقها المدين ودائنوه، ويكون القائم بالتنفيذ ملزمًا بالثمن إن لم يستوفه من المشتري فورًا ولم يبادر بإعادة البيع على ذمته، ويعتبر محضر البيع سندًا تنفيذيًّا بالنسبة إليه.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 277",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
