      "sourceNotes": [],
      "text": "1. إذا رفعت دعوى استرداد ثانية من نفس المسترد وكانت دعواه الأولى قد اعتبرت كأن لم تكن أو حُكم باعتبارها كذلك أو برفضها أو بعدم قبولها، أو بعدم اختصاص المحكمة أو ببطلان صحيفتها أو بسقوط الخصومة فيها أو بقبول تركها، فلا يوقف البيع إلا إذا قررت المحكمة المختصة بوقفه، ويسري هذا الحكم إذا جددت دعوى الاسترداد بعد شطبها أو وقفها.\n2. يسري الحكم المشار إليه في البند (1) من هذه المادة، إذا رفعت دعوى استرداد ثانية من مسترد آخر وتعتبر الدعوى ثانية متى كانت تالية في تاريخ رفعها ولو قبل زوال الأثر الواقف للبيع المترتب على رفع الدعوى الأولى.",
