      "sourceNotes": [],
      "text": "1. يقدم الحاجز طلبًا بالحجز على العقار إلى قاضي التنفيذ، ويتضمن الطلب البيانات الآتية:-\n‌ أ. اسم الطالب ولقبه ومهنته وموطنه ومحل عمله وموطنه المختار في دائرة المحكمة التي يجري فيها التنفيذ إذا لم يكن له موطن أو محل عمل فيها.\n‌ ب. اسم المطلوب الحجز عليه ولقبه ومهنته وموطنه ومحل عمله.\n‌ ج. وصف العقار المطلوب الحجز عليه مع بيان موقعه ومساحته وحدوده أو رقمه ومنطقته العقارية وأية بيانات أخرى تفيد في تعيينه، وذلك طبقًا لما هو ثابت في السجلات الرسمية المعدة لذلك.\n2. للدائن أن يستصدر أمرًا بعريضة من قاضي التنفيذ بالترخيص للقائم بالتنفيذ لدخول العقار، للحصول على البيانات اللازمة لوصفه وتحديد مشتملاته، ولا يجوز التظلم من هذا الأمر.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 285",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
