      "sourceNotes": [],
      "text": "1. إذا تبين لقاضي التنفيذ أن طلب الحجز على العقار قد استوفى شروطه القانونية أصدر قراره بالحجز ويجريه القائم بالتنفيذ إلكترونيًّا أو يبلغ هذا القرار إلى الدائرة المختصة بتسجيل العقارات للتأشير في السجلات الخاصة بهذا العقار وتحديد الساعة والتاريخ.\n2. يترتب على تسجيل قرار الحجز، اعتبار العقار محجوزًا.\n3. على الدائرة المختصة المحجوز لديها العقار أن تُطلع قاضي التنفيذ من واقع السجل العقاري، بالدائنين أصحاب الحقوق المقيدة وموطن كل منهم ومحل عمله وفيما إذا كانت توجد أية موانع تعيق التصرف بالعقار.",
