      "useCase": "ابنِ ملف حجز عقار وبيعه: التسجيل، الإخطار، التثمين، شروط البيع، المزايدة، رسو المزاد، والاستحقاق.",
      "sourceNotes": [],
      "text": "1. بعد إتمام الحجز، يجوز للمدين أن يقدم لقاضي التنفيذ طلبًا ببيع العقار المحجوز لأحد المشترين، ويرفق بطلبه ثمن البيع وموافقة المشتري عليه، ويعرض ذلك على الدائن الحاجز أو الدائنين الحاجزين إن تعددوا إذا كان ثمن المبيع أقل من الدين المحجوز من أجله وذلك خلال (7) سبعة أيام من تاريخ تقديم الطلب، فإذا لم يعترضوا خلال (7) سبعة أيام من تاريخ إخطارهم أو عند موافقتهم يتم إجراء البيع وإيداع الثمن خزينة المحكمة لصالح الدائنين.\n2. على قاضي التنفيذ قبل مباشرة بيع العقار بطريق المزاد أن يخطر المدين بأداء الدين خلال (15) خمسة عشر يومًا من تاريخ التبليغ وإلا بيع العقار بطريق المزايدة، وللمدين أن يطلب خلال هذه المدة إرجاء البيع ولقاضي التنفيذ إجابة الطلب في أيٍّ من الحالتين الآتيتين:-\nأ‌. إذا كانت إيرادات العقار لمدة (5) خمس سنوات تكفي لسداد الدين والفوائد والرسوم والنفقات، لقاضي التنفيذ في هذه الحالة أن يفوض الدائن تحت إشرافه في تحصيل إيرادات العقار حتى السداد التام، وإذا حدث طارئ يحول دون حصول الدائن على حقوقه بصورة منتظمة فعلى قاضي التنفيذ بناءً على طلب الدائن الاستمرار في إجراءات بيع العقار.\nب‌. إذا كانت إيرادات العقار لمدة (5) خمس سنوات لا تكفي لسداد الدين والفوائد والرسوم والنفقات وكان للمدين إيرادات أخرى بالإضافة إلى إيرادات العقار تكفي لسداد الدين على أقساط خلال مدة لا تجاوز المدة المشار إليها في هذه الفقرة وذلك بالضمانات التي يراها، وإذا قصر المدين في دفع قسط من هذه الأقساط فعلى قاضي التنفيذ -بناءً على طلب الدائن- الاستمرار في إجراء بيع العقار.\n3. إذا انقضت مدة الإخطار المنصوص عليها في البند (1) من هذه المادة ولم يدفع المدين أو لم يقدم طلبًا بإرجاء البيع أو رفض هذا الطلب فعلى قاضي التنفيذ أن يُحدد مكان البيع ويومه والمدة التي تجرى خلالها المزايدة.\n4. يعين قاضي التنفيذ قبل الإعلان عن البيع خبيرًا أو أكثر لتقدير ثمن العقار، وذلك خلال مهلة لا تجاوز (15) خمسة عشر يومًا من تاريخ تكليف القاضي له بالمهمة.\n5. على القائم بالتنفيذ إخطار كل من المدين والحائز والكفيل العيني بمكان البيع ويومه والمدة التي تجرى خلالها المزايدة، وبالإعلان عن البيع قبل اليوم المحدد لإجرائه بمدة لا تزيد على (30) ثلاثين يومًا، وذلك بإدراج الإعلان على الموقع الإلكتروني للمحكمة أو بالنشر في صحيفتين يوميتين تصدران في الدولة، وتعلق نسخة من الإعلان في مكان بارز من العقار وأخرى على لوحة إعلانات المحكمة، أو بأي وسيلة أخرى يراها قاضي التنفيذ مناسبة.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 288",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(5).md"
