      "useCase": "ابنِ ملف حجز عقار وبيعه: التسجيل، الإخطار، التثمين، شروط البيع، المزايدة، رسو المزاد، والاستحقاق.",
      "sourceNotes": [],
      "text": "1. لا ينفذ تصرف المدين أو الحائز أو الكفيل العيني في العقار، ولا ينفذ كذلك ما يترتب عليه من رهن أو امتياز في حق الحاجزين ولو كانوا دائنين عاديين، ولا في حق الراسي عليه المزاد، إذا كان التصرف أو الرهن أو الامتياز قد حصل تسجيله بعد تسجيل قرار الحجز.\n2. تلحق بالعقار ثماره وإيراداته عن المدة التالية لتسجيل قرار الحجز، ويُودع الإيراد وثمن الثمار والمحصولات خزانة المحكمة، وإذا لم يكن العقار مؤجرًا اعتبر المحجوز عليه حارسًا إلى أن يتم البيع، وإذا كان العقار مؤجرًا اعتبرت الأجرة المستحقة عن المدة التالية لتسجيل طلب الحجز محجوزة تحت يد المستأجر وذلك بمجرد تكليفه من الحاجز أو أي دائن بيده سند تنفيذي بعدم دفعها للمدين، وإذا وفَّى المستأجر الأجرة قبل هذا التكليف صح وفاؤه وسُئل عنها المحجوز عليه بوصفه حارسًا.\n3. إذا كان عقد الإيجار قد سُجِّل قبل تكليف المستأجر بالوفاء ظل العقد نافذًا في حق الحاجز والدائنين أصحاب الحقوق المقيدة قبل التسجيل.",
