      "useCase": "ابنِ ملف حجز عقار وبيعه: التسجيل، الإخطار، التثمين، شروط البيع، المزايدة، رسو المزاد، والاستحقاق.",
      "sourceNotes": [],
      "text": "على الدائن قبل البدء في إجراءات المزايدة أن يقوم بإيداع مبلغ يُقدره قاضي التنفيذ لتغطية نفقات ومصروفات بيع العقار بما في ذلك مقابل أتعاب المحاماة، ويُخصم هذا المبلغ من ثمن بيع العقار ويُرد للدائن.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 295",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(5).md"
