      "sourceNotes": [],
      "text": "1. يصدر حكم رسو المزاد بديباجة الأحكام، ويشتمل على صورة من طلب الحجز على العقار، وبيان الإجراءات التي اتبعت في شأنه، وفي الإعلان عن البيع، وصورة من محضر جلسة البيع، ويشتمل منطوقه على أمر المدين أو الحائز أو الكفيل العيني، بتسليم العقار لمن حكم برسو المزاد عليه، ويجب إيداع الحكم ملف القضية في اليوم التالي لصدوره.\n2. لا يُعلن الحكم المشار إليه في البند (1) من هذه المادة، ويجري تنفيذه جبرًا بأن يكلف المدين أو الحائز أو الكفيل العيني أو الحارس حسب الأحوال، الحضور في مكان التسليم في اليوم والساعة المحددين لإجرائه، على أن يحصل الإعلان بذلك قبل اليوم المعين للتسليم بيومين على الأقل.\n3. إذا كان في العقار منقولات تعلق بها حق لغير المحجوز عليه وجب على طالب التنفيذ أن يطلب بعريضة من قاضي التنفيذ اتخاذ التدابير اللازمة للمحافظة على حقوق أصحاب الشأن، وله أن يسمع أقوالهم كلما اقتضى الحال ذلك قبل إصدار أمره.\n4. إذا تعذر نقل ملكية العقار المبيع أو جزء منه لأي سبب لا دخل للأطراف فيه فلقاضي التنفيذ إلغاء حكم إرساء المزايدة وإعادة الحال إلى ما كان عليه.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 299",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
