      "sourceNotes": [],
      "text": "1. على قاضي التنفيذ بناءً على طلب ذوي الشأن، أن يطلب من الإدارة المختصة بتسجيل العقارات تسجيل حكم مرسي المزاد بعد قيام من حكم برسو المزاد عليه إيداع كامل الثمن، ما لم يكن قد أعفي من الإيداع، وتتبع في تسجيل الحكم القواعد المقررة في التسجيل العقاري.\n2. يترتب على التسجيل المشار إليه في البند (1) من هذه المادة تطهير العقار المبيع من حقوق الامتياز والرهون التأمينية والحيازية التي أعلن أصحابها وفقًا للمادة (286) من هذا القانون، ولا يبقى إلا حقهم في الثمن.",
