      "sourceNotes": [],
      "text": "1. يجوز للغير طلب بطلان إجراءات التنفيذ مع طلب استحقاق العقار المحجوز عليه أو بعضه وذلك بدعوى ترفع بالإجراءات المعتادة أمام المحكمة المختصة، ويختصم فيها الدائن الحاجز والدائنون المشار إليهم في المادة (286) من هذا القانون والمدين أو الحائز أو الكفيل العيني، وتقضي المحكمة في أول جلسة بوقف إجراءات البيع إذا اشتملت صحيفة الدعوى على بيان دقيق لأدلة الملكية أو لوقائع الحيازة أو الاستحقاق التي تستند إليها الدعوى وأرفقت بها المستندات التي تؤيدها.\n2. إذا حل اليوم المعين للبيع قبل أن تقضي المحكمة بالوقف، فيجوز لرافع الدعوى أن يطلب من قاضي التنفيذ وقف البيع بشرط أن يودع ملف التنفيذ صورة رسمية من صحيفة الدعوى المعلنة.\n3. لا يجوز الطعن في الأحكام الصادرة وفقًا للبندين (1) و(2) من هذه المادة بوقف البيع أو المضي فيه.\n4. لا تقبل دعوى الاستحقاق إلا بعد إيداع تأمين مقداره (10.000) عشرة آلاف درهم عند قيدها ويرد عند قبولها ويصادر في حالة الرفض.",
