      "sourceNotes": [],
      "text": "1. متى تم الحجز على نقود لدى المدين، أو تم بيع المال المحجوز، أو انقضت (10) عشرة أيام من تاريخ التقرير بما في الذمة في حجز ما للمدين لدى الغير، توزع حصيلة التنفيذ على الدائنين الحاجزين ومن اعتبر طرفًا في الإجراءات دون أي إجراء آخر، ولو كانت الحصيلة لا تكفي لوفاء كامل حقوقهم.\n2. يعتبر جميع الدائنين المنفذ لهم في المجموعات التنفيذية وملفات التنفيذ المضمومة طرفًا في الإجراءات بمفهوم الفقرة السابقة ولو لم يقدموا طلبًا بذلك ويدرجون في قائمة توزيع حصيلة التنفيذ وفقًا لمقتضيات المواد من (311- 314) من هذا القانون.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 310",
