      "sourceNotes": [],
      "text": "1. يجب على القائم بالتنفيذ -في حالة التنفيذ بتسليم منقول أو عقار- أن يتوجه إلى المكان الذي به الشيء لتسليمه للطالب، وعليه أن يبين في محضره الأشياء محل التسليم والسند التنفيذي، وتاريخ إعلانه، وإذا كان التسليم واردًا على عقار مشغول بحائز عرضي، نبه عليه القائم بالتنفيذ بالاعتراف بالحائز الجديد بعد إتمام إجراء تسليم العقار.\n2. إذا كانت الأشياء المراد تسليمها محجوزًا عليها، فلا يجوز للقائم بالتنفيذ تسليمها للطالب، وعلى القائم بالتنفيذ إخبار الدائن الحاجز.\n3. يصدر قاضي التنفيذ الأوامر اللازمة للمحافظة على حقوق ذوي الشأن، بناءً على طلب صاحب المصلحة أو القائم بالتنفيذ.",
