      "useCase": "حاكي التنفيذ بالتسليم أو الإخلاء أو العمل والامتناع، وحدد متى تستخدم الغرامة اليومية وحدودها.",
      "sourceNotes": [],
      "text": "1. على القائم بالتنفيذ إخبار الملزم بإخلاء العقار، باليوم الذي سيتولى فيه تنفيذ الإخلاء، وذلك قبل اليوم المحدد بثلاثة أيام على الأقل، وعند حلول الموعد المحدد، يقوم بتمكين الطالب من حيازة العقار، وإذا كان بالعقار المذكور منقولات غير واجب تسليمها لطالب الإخلاء ولم ينقلها صاحبها فورًا، وجب على القائم بالتنفيذ أن يعهد بحراستها في ذات المكان إلى الطالب، أو بنقلها إلى مكان آخر على نفقة المنفذ ضده إذا لم يوافق الطالب على الحراسة، وإذا كانت تلك المنقولات تحت الحجز أو الحراسة وجب على القائم بالتنفيذ إخبار الدائن الذي وقع الحجز أو الحراسة بناءً على طلبه، وعلى القائم بالتنفيذ في الحالتين رفع الأمر إلى قاضي التنفيذ، لاتخاذ ما يراه لازمًا للمحافظة على حقوق ذوي الشأن.\n2. يحرر القائم بالتنفيذ محضرًا يبين فيه السند التنفيذي وتاريخ إعلانه، ووصف العقار محل الإخلاء والمنقولات غير الواجب تسليمها للطالب، والإجراء الذي اتخذ في شأنها.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 316",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(5).md"
