      "useCase": "حاكي التنفيذ بالتسليم أو الإخلاء أو العمل والامتناع، وحدد متى تستخدم الغرامة اليومية وحدودها.",
      "sourceNotes": [],
      "text": "1. يجب على من يطلب التنفيذ الجبري بالتزام بعمل أو امتناع عن عمل، أن يقدم طلبًا إلى قاضي التنفيذ لكي يُحدد الطريقة التي يتم بها هذا التنفيذ، ويرفق بالطلب السند التنفيذي وإعلانه.\n2. يقوم قاضي التنفيذ بعد إعلان الطرف الآخر لسماع أقواله، بإصدار أمره بتحديد الطريقة التي يتم بها التنفيذ، وتعيين قائم بالتنفيذ للقيام به، والأشخاص الذين يكلفون بإتمام العمل أو الإزالة.",
