      "useCase": "حاكي التنفيذ بالتسليم أو الإخلاء أو العمل والامتناع، وحدد متى تستخدم الغرامة اليومية وحدودها.",
      "sourceNotes": [],
      "text": "1. إذا تعذر التنفيذ العيني بالطريقة المحددة في المادة (317) من هذا القانون، أو اقتضى التنفيذ قيام المدين به بنفسه ولم يقم بذلك، فلقاضي التنفيذ أن يلزمه بغرامة يومية لا تقل عن (1.000) ألف درهم ولا تزيد على (10.000) عشرة آلاف درهم، تصرف كتعويض للمنفذ له عن التأخير، على ألا تتجاوز مجموع الغرامات أصل الدين محل التنفيذ.\n2. لقاضي التنفيذ الحق في إلغاء الغرامة، أو جزء منها إذا بادر المنفذ ضده بالتنفيذ، قبل صرفها فعليًّا.\n3. تسري أحكام البند (1) من هذه المادة، على الممثل القانوني للشخص الاعتباري، وعلى المتسبب شخصيًّا في عرقلة التنفيذ من العاملين لديه.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 318",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(5).md"
