      "useCase": "قيّم طلب حبس المدين أو تأجيله أو إسقاطه، ووازن بين القدرة على الوفاء وموانع الحبس وضماناته.",
      "sourceNotes": [],
      "text": "1. لقاضي التنفيذ أن يصدر أمرًا بناءً على طلب يقدم من المحكوم له، بحبس المدين إذا امتنع عن تنفيذ أي سند تنفيذي، ما لم يثبت عدم قدرته على الوفاء، ولا يعتبر المدين مقتدرًا على الوفاء إذا ثبتت ملاءته كليًّا على أموال لا يجوز الحجز عليها أو بيعها.\n2. لا يقبل من المدين ادعاء عدم القدرة على الوفاء إذا امتنع عن الوفاء، في أيٍّ من الحالات الآتية:\nأ‌. إذا قام بتهريب أمواله أو إخفائها بقصد الإضرار بالدائن، واستحال على الدائن بسبب ذلك التنفيذ على تلك الأموال.\nب‌. إذا كان الدين قسط أو أكثر من الأقساط المقررة على المدين، أو كان المدين ممن كفلوا المدين الأصلي بالدفع أمام المحكمة أو قاضي التنفيذ، إلا إذا أثبت المدين حصول وقائع جديدة أثرت على ملاءته وجعلته غير قادر على دفع الأقساط أو قيمة الكفالة أو أي جزء منها، بعد تقرير هذه الأقساط عليه أو بعد إعطائه الكفالة.\n3. يأمر قاضي التنفيذ بحبس المدين في الحالات المبينة بالفقرتين (أ) و(ب) من البند (2) من هذه المادة مدة لا تزيد على شهر ويجوز تجديدها لمدد أخرى، فإذا كان المدين ممن لا يخشى هربه وله إقامة، فلا يجوز أن تتجاوز مدد الحبس (6) ستة أشهر متتالية، ويجوز تجديد حبسه بعد انقضاء (90) تسعين يومًا على إخلاء سبيله إذا بقي ممتنعًا عن التنفيذ، وذلك بشرط ألا يتعدى مجموع مدد حبس المدين (36) ستة وثلاثين شهرًا مهما تعدد الدين أو الدائنون وذلك في حال تزامن سندات التنفيذ المعنية، ما لم يتعلق الأمر بدين ناتج عن جرائم مالية عمدية، فيجوز أن تصل مدد الحبس إلى (60) ستين شهرًا.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 319",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
