      "sourceNotes": [],
      "text": "1. على قاضي التنفيذ قبل إصداره أمر الحبس أن يجري تحقيقًا مختصرًا إذا لم تكفه المستندات المؤيدة للطلب.\n2. يجوز للقاضي أن يمنح المدين مهلة للوفاء لا تجاوز (6) ستة أشهر متتالية، أو تقسيط المبلغ المنفذ من أجله على أقساط مناسبة لا تجاوز (3) ثلاث سنوات بضمانات أو تدابير احتياطية يقدرها القاضي إذا كان يخشى هروب المدين من الدولة.\n3. يكون التظلم أو الاستئناف من الأمر الوارد في البندين (1) و(2) من هذه المادة بالإجراءات المقررة في المادة (209) من هذا القانون.",
