      "useCase": "اختبر طلب منع المدين من السفر، وشروطه، ومدد رفع الدعوى والتنفيذ، وأسباب سقوط الأمر.",
      "sourceNotes": [],
      "text": "يبقى أمر المنع من السفر ساري المفعول حتى ينقضي التزام المدين قبل دائنه الذي استصدر الأمر- لأي سبب من الأسباب- ومع ذلك يأمر القاضي المختص بسقوط الأمر في أيٍّ من الأحوال الآتية:-\n1. إذا سقط أي شرط من الشروط اللازم توفرها للأمر بالمنع من السفر.\n2. إذا وافق الدائن كتابة على إسقاط الأمر.\n3. إذا قدم المدين كفالة مصرفية كافية، أو كفيلاً مقتدرًا يقبله القاضي، ويكون محضر الكفالة المشتمل على تعهد الكفيل مصحوبًا بالحكم أو الأمر الصادر بإلزام المدين سندًا تنفيذيًّا قبله بما قضى به هذا الحكم.\n4. إذا أودع المدين خزانة المحكمة مبلغًا من النقود مساويًا للدين والمصروفات، وخصص للوفاء بحق الدائن الذي صدر الأمر بناءً على طلبه، ويعتبر هذا المبلغ محجوزًا عليه بقوة القانون لصالح الدائن.\n5. إذا لم يقدم الدائن للقاضي ما يدل على رفع الدعوى بالدين خلال (8) ثمانية أيام من صدور الأمر بالمنع من السفر، أو لم يبدأ في تنفيذ الحكم النهائي الصادر لصالحه خلال (30) ثلاثين يومًا من تاريخ صيرورته قطعيًّا.\n6. إذا انقضت (3) ثلاث سنوات على آخر إجراء صحيح من إجراءات تنفيذ الحكم النهائي بالدين الصادر أمر المنع من السفر لاقتضائه دون أن يتقدم الدائن المحكوم له إلى قاضي التنفيذ بطلب الاستمرار في مباشرة إجراءات تنفيذ ذلك الحكم.\n7. إذا ورد طلب من الجهات المختصة بما يفيد أن إقامة الممنوع من السفر في الدولة أصبحت غير قانونية ويتعين إبعاده منها ولم يثبت وجود أموال له في الدولة يمكن التنفيذ عليها.",
      "source": "قانون الإجراءات المدنية الإماراتي · المادة 325",
      "sourceUrl": "https://uaelegislation.gov.ae/ar/legislations/1602",
      "sourceFile": "Pasted markdown(5).md"
