      "text": "1. تسجل وتحفظ سجلات التقاضي عن بعد إلكترونيًّا قبل تفريغها، ويكون لها صفة السرية، ولا يجوز تداولها أو الاطلاع عليها أو نسخها أو حذفها من النظام المعلوماتي الإلكتروني إلا بإذن من المحكمة المختصة حسب الأحوال.\n2. يجوز للمحكمة الاستغناء عن التسجيل إذا دونت إجراءات التقاضي عن بُعد مباشرةً أثناء الجلسة في ملف الدعوى الإلكتروني واعتمدت من رئيسها.",
